   pub const MAX_ABSOLUTE_Z: f64 = 3.0;

   /// Scales a median absolute deviation to a standard deviation.
   /// `1 / Phi^-1(0.75)`. ...
   const MAD_TO_DEVIATION: f64 = 1.482_602_218_505_602;

   #[derive(Debug, Clone, PartialEq)]
   pub struct Standardized { location: f64, scale: f64, scores: Vec<f64> }

   impl Standardized {
       pub fn location(&self) -> f64 { self.location }   // sample median
       pub fn scale(&self) -> f64 { self.scale }         // MAD scaled to an sd
       pub fn scores(&self) -> &[f64] { &self.scores }
       pub fn outliers(&self, max_absolute_z: f64) -> Vec<usize> { ... }
   }

   fn median_of(sample: &mut [f64]) -> Option<f64> { ... }

   pub fn standardize(sample: &[f64]) -> Result<Standardized, AbsenceReason> {
       if sample.len() < 3 { return Err(AbsenceReason::InsufficientObservations); }
       if sample.iter().any(|value| !value.is_finite()) { return Err(AbsenceReason::NotReported); }
       let location = median_of(&mut sample.to_vec()).expect("a non-empty sample");
       let mut deviations: Vec<f64> = sample.iter().map(|value| (value - location).abs()).collect();
       let scale = median_of(&mut deviations).expect("a non-empty sample") * MAD_TO_DEVIATION;
       if !(scale > 0.0) || !scale.is_finite() { return Err(AbsenceReason::OutOfPolicyRange); }
       Ok(Standardized { location, scale,
           scores: sample.iter().map(|value| (value - location) / scale).collect() })
   }

   pub fn robust_mean(sample: &[f64], max_absolute_z: f64) -> Result<f64, AbsenceReason> {
       let standardized = standardize(sample)?;
       let kept: Vec<f64> = sample.iter().zip(standardized.scores())
           .filter(|(_, score)| score.abs() <= max_absolute_z)
           .map(|(value, _)| *value).collect();
       if kept.len() < 3 { return Err(AbsenceReason::InsufficientObservations); }
       Ok(kept.iter().sum::<f64>() / kept.len() as f64)
   }
   ```
