pub struct OperatingCashReading {
    pub years: Vec<AnnualValue>,
    /// Fiscal years absent under rule 4 — reported by name, per contract.
    pub disagreeing_tier_years: Vec<i32>,
}

fn extract_operating_cash(facts: &serde_json::Value) -> OperatingCashReading {
    let aggregate = extract_driver_annual(facts, policy::OPERATING_CASH_AGGREGATE);
    let cash = extract_driver_annual(facts, policy::CASH_AND_EQUIVALENTS);

    let mut tier_by_year = HashMap::<i32, Vec<AnnualValue>>::new();
    for value in extract_driver_vintages(facts, policy::SHORT_TERM_INVESTMENTS)
        .latest_by_concept().into_iter().flatten()
    { tier_by_year.entry(value.year).or_default().push(value); }
    let mut disagreeing_tier_years = Vec::new();
    tier_by_year.retain(|year, filed| {
        let agreed = filed.iter().all(|value| value.value_dollars == filed[0].value_dollars);
        if !agreed { disagreeing_tier_years.push(*year); }
        agreed
    });

    let mut by_year = HashMap::<i32, AnnualValue>::new();
    for value in cash {
        // Rule 4 makes the YEAR absent, not merely its investments term.
        if disagreeing_tier_years.contains(&value.year) { continue; }
        let composed = match tier_by_year.get(&value.year) {
            Some(filed) => {
                let investments = &filed[0];
                let end = value.provenance.end.max(investments.provenance.end);
                let Some(provenance) = AnnualProvenance::composed(end, [&value.provenance, &investments.provenance]) else { continue; };
                AnnualValue { year: value.year, value_dollars: value.value_dollars + investments.value_dollars, provenance }
            }
            None => value,
        };
        by_year.insert(composed.year, composed);
    }
    // Rule 1, applied last so it supersedes both the composition and rule 4.
    for value in aggregate {
        disagreeing_tier_years.retain(|year| *year != value.year);
        by_year.insert(value.year, value);
    }
    disagreeing_tier_years.sort_unstable();
    OperatingCashReading { years: sorted_by_year(by_year), disagreeing_tier_years }
}
```
