        let sic_excludes = matches!(sic, Ok(Some(code)) if SECTION_11_EXCLUDED_SIC.contains(&code));

        let class = yahoo.fetch_symbol(symbol).ok().and_then(|fetched| {
            let fundamentals = fetched.fundamentals?;
            Some(classify_business(
                fundamentals.sector_name.as_deref(),
                fundamentals.industry_name.as_deref(),
                fundamentals.sector_key.as_deref(),
                fundamentals.industry_key.as_deref(),
                false,
            ))
        });

        let described = match sic {
            Ok(Some(code)) => format!("SIC {code}"),
            Ok(None) => "no SIC on file".to_string(),
            Err(ref reason) => format!("SIC lookup: {reason}"),
        };
        match section_11_verdict(sic_excludes, class) {
            Section11Verdict::Excluded(Section11Basis::Classifier) => {
                let class = class.expect("the classifier basis carries a class");
                self.excluded.push(format!("{symbol}({class:?})"));
                false
            }
            Section11Verdict::Excluded(Section11Basis::FiledSicAloneWithNoClassifier) => {
                self.excluded
                    .push(format!("{symbol}(classifier unavailable; {described})"));
                false
            }
            Section11Verdict::AdmittedOverSicObjection => {
                self.disagreements
                    .push(format!("{symbol}(SIC excludes, classifier admits)"));
                true
            }
            Section11Verdict::AdmittedUnplaced => {
                self.unclassified
                    .push(format!("{symbol}(classifier unavailable; {described} admits)"));
                true
            }
