```rust
    fn return_on_capital(&self, frame: &MarketFrame) -> Observation<f64> {
        let provenance = self.provenance("invested_capital", frame);
        let returns = self.annual_returns_on_capital();
        // An issuer that filed none of the terms keeps the reason it always
        // gave, rather than inheriting whatever the aggregator says about an
        // empty slice. ...
        if returns.is_empty() {
            return Observation::absent(AbsenceReason::ProviderUnavailable, provenance);
        }
        match robust_centre(&returns) {
            Ok(centre) => measured_or_absent(
                centre.centre(),
                centre.variance_of_centre(),
                UncertaintyBasis::SampleVariance { observations: centre.retained() as u32 },
                provenance,
            ),
            Err(reason) => Observation::absent(reason, provenance),
        }
    }

    fn capital_returns_by_year(&self) -> Vec<(f64, f64)> {
        self.annuals.iter().filter_map(|annual| {
            let pretax = annual.pretax_income?;
            let equity = annual.stockholders_equity?;
            let debt = annual.debt.unwrap_or(0.0);
            let invested = equity + debt;
            if invested <= 0.0 { return None; }
            let tax = f64::from(annual.statutory_federal_tax_bps) / 10_000.0;
            let nopat = (pretax + annual.interest_expense) * (1.0 - tax);
            Some((invested, nopat))
        }).collect()
    }

    /// **Basis points**, not a fraction. [doc records the -507x..-40,730x failure]
    fn annual_returns_on_capital(&self) -> Vec<f64> {
        self.capital_returns_by_year().into_iter()
            .map(|(invested, nopat)| nopat / invested * 10_000.0).collect()
    }

